SELECT CASE WHEN d.budget >= 4490000 THEN 'high' WHEN d.budget >= 1403000 THEN 'mid' ELSE 'low' END budget_bucket, d.dept_name, SORT_ARRAY(COLLECT_SET(e.level)) level_list, ROUND((100 * SUM(CASE WHEN e.level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_l3 FROM employees e INNER JOIN departments d ON e.dept_id = d.id GROUP BY CASE WHEN d.budget >= 4490000 THEN 'high' WHEN d.budget >= 1403000 THEN 'mid' ELSE 'low' END, d.dept_name ORDER BY dept_name DESC;
